body.script:
//
  (async function () {
    var XHTML = "http://www.w3.org/1999/xhtml";
    var body = document.body || document.getElementsByTagName("body")[0] || document.documentElement;

    // Folder this file is served from (sw.js, app.html and index.html all live here).
    var base = location.href.split("#")[0].split("?")[0].replace(/[^\/]*$/, "");

    try {
      if (!("serviceWorker" in navigator)) throw new Error("unsupported");
      await navigator.serviceWorker.register(base + "sw.js", { scope: base });
      await navigator.serviceWorker.ready;

      // app.html is a virtual address: the service worker builds it from ?src=
      var src = base + "app.html?src=" + encodeURIComponent(base + "index.html");

      var iframe = document.createElementNS(XHTML, "iframe");
      iframe.setAttribute("src", src);
      iframe.setAttribute("allow", "autoplay; fullscreen; pointer-lock; gamepad; clipboard-read; clipboard-write");
      iframe.setAttribute("allowfullscreen", "");
      body.appendChild(iframe);
    } catch (err) {
      var p = document.createElementNS(XHTML, "p");
      p.setAttribute("style", "font-family:system-ui,sans-serif;color:#444;padding:24px;");
      p.textContent = "This page could not be loaded. Reload to try again.";
      body.appendChild(p);
    }
  })();
//
